import base64, json, os

# Decode README from develop
readme_b64 = ""
readme_dev = base64.b64decode(readme_b64.strip()).decode("utf-8")

# Decode types/index.ts from develop
types_b64 = ""
types_dev = base64.b64decode(types_b64.strip()).decode("utf-8")

REPO = r"d:\软件工程\SoftwareProject-main\SoftwareProject-main"

# Save develop versions for comparison
with open(os.path.join(REPO, "_develop_README.md"), "w", encoding="utf-8") as f:
    f.write(readme_dev)
print(f"develop README: {len(readme_dev)} chars, {len(readme_dev.splitlines())} lines")

with open(os.path.join(REPO, "_develop_types.ts"), "w", encoding="utf-8") as f:
    f.write(types_dev)
print(f"develop types/index.ts: {len(types_dev)} chars, {len(types_dev.splitlines())} lines")

# Compare local types with develop
local_types = open(os.path.join(REPO, "frontend/src/types/index.ts"), encoding="utf-8").read()
if local_types.strip() == types_dev.strip():
    print("types/index.ts: IDENTICAL (only line endings differ)")
else:
    print(f"types/index.ts: DIFFERENT (local={len(local_types)} vs develop={len(types_dev)})")
    # Show first difference
    for i, (a, b) in enumerate(zip(local_types, types_dev)):
        if a != b:
            print(f"  First diff at char {i}: local={repr(a)} develop={repr(b)}")
            break
